package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	// Validate sort parameter - only allow known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortBy != "" && !allowedSorts[sortBy] {
		sortBy = "id"
	}
	if sortBy == "" {
		sortBy = "id"
	}

	// Build query - category is user-controlled and directly interpolated
	query := fmt.Sprintf(
		"SELECT id, name, price, sku FROM products WHERE category = '%s' ORDER BY %s",
		category, sortBy,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// bulkUpdate handles inventory updates via POST with JSON body
func bulkUpdate(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var updates []struct {
		SKU      string  `json:"sku"`
		NewPrice float64 `json:"new_price"`
		Note     string  `json:"note"`
	}

	if err := json.NewDecoder(r.Body).Decode(&updates); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	for _, u := range updates {
		// Note field is logged with string interpolation into audit table
		auditQuery := fmt.Sprintf(
			"INSERT INTO audit_log (action, detail) VALUES ('price_update', 'SKU=%s note=%s')",
			u.SKU, u.Note,
		)
		db.Exec(auditQuery)

		// Actual update uses parameterized query
		db.Exec("UPDATE products SET price = $1 WHERE sku = $2", u.NewPrice, u.SKU)
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"updated"}`))
}

// healthCheck endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte(`{"status":"ok"}`))
}

func loggingMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Log request details including raw query for debugging
		log.Printf("%s %s?%s from %s", r.Method, r.URL.Path, r.URL.RawQuery, r.RemoteAddr)
		// Strip X-Forwarded-For to prevent spoofing (or so we think)
		r.Header.Del("X-Forwarded-For")
		next(w, r)
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	http.HandleFunc("/api/products/search", loggingMiddleware(searchProducts))
	http.HandleFunc("/api/products/bulk-update", loggingMiddleware(bulkUpdate))
	http.HandleFunc("/health", healthCheck)

	log.Printf("Starting server on :%s", port)
	_ = strings.NewReplacer() // unused, leftover from removed sanitization attempt
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
